import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Select from 'flarum/common/components/Select';
import Button from 'flarum/common/components/Button';
import { applyThemeInline, option } from '../../common/theme';
import { forumConfig, userConfig } from '../config';
const SWATCHES = ['#6366f1', '#8b5cf6', '#d946ef', '#ec4899', '#f43f5e', '#f97316', '#eab308', '#22c55e', '#14b8a6', '#06b6d4', '#3b82f6', '#64748b'];

/**
 * Lets members personalize the theme, within what the admin allows.
 */
export default class PersonalThemeSettings extends Component {
  saving = false;
  pref(key) {
    return app.session.user.preferences()?.[key] ?? null;
  }
  save(prefs) {
    this.saving = true;
    app.session.user.savePreferences(prefs).then(() => applyThemeInline(document, userConfig())).finally(() => {
      this.saving = false;
      m.redraw();
    });
  }
  view() {
    const config = forumConfig();
    const t = key => app.translator.trans(`fy-theme.forum.settings.${key}`);
    return m("div", {
      className: "FyUserSettings"
    }, config.userAccent ? m("div", {
      className: "Form-group"
    }, m("label", null, t('accent_label')), m("div", {
      className: "FyUserSettings-swatches"
    }, m("button", {
      type: "button",
      className: 'FyUserSettings-swatch FyUserSettings-swatch--reset' + (!this.pref('fyAccent') ? ' active' : ''),
      title: app.translator.trans('fy-theme.forum.settings.forum_default', {}, true),
      disabled: this.saving,
      onclick: () => this.save({
        fyAccent: null
      })
    }), SWATCHES.map(color => m("button", {
      type: "button",
      className: 'FyUserSettings-swatch' + (this.pref('fyAccent') === color ? ' active' : ''),
      style: {
        background: color
      },
      title: color,
      disabled: this.saving,
      onclick: () => this.save({
        fyAccent: color
      })
    })))) : null, config.userDensity ? m("div", {
      className: "Form-group"
    }, m("label", null, t('density_label')), m(Select, {
      value: this.pref('fyDensity') || '',
      options: {
        '': app.translator.trans('fy-theme.forum.settings.forum_default', {}, true),
        ...option('density').choices
      },
      disabled: this.saving,
      onchange: value => this.save({
        fyDensity: value || null
      })
    })) : null, config.userFontScale ? m("div", {
      className: "Form-group"
    }, m("label", null, t('font_scale_label'), " ", m("strong", null, this.pref('fyFontScale') ?? config.fontScale, "%")), m("input", {
      type: "range",
      className: "FormControl",
      min: option('fontScale').min,
      max: option('fontScale').max,
      step: 5,
      value: this.pref('fyFontScale') ?? config.fontScale,
      disabled: this.saving,
      onchange: e => this.save({
        fyFontScale: parseInt(e.target.value, 10)
      })
    }), this.pref('fyFontScale') !== null ? m(Button, {
      className: "Button Button--link",
      onclick: () => this.save({
        fyFontScale: null
      })
    }, t('reset')) : null) : null);
  }
}
flarum.reg.add('soup-97-fy-theme', 'forum/components/PersonalThemeSettings', PersonalThemeSettings);