import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import { isSafeUrl } from '../../common/theme';
export function parseLinks(raw) {
  return raw.split('\n').map(line => line.split('|').map(part => part.trim())).filter(([label, url]) => label && url && isSafeUrl(url)).map(([label, url]) => ({
    label,
    url
  }));
}
