import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
/**
 * Reading progress bar and back-to-top button. Both update via direct DOM
 * writes on scroll, so scrolling never triggers a Mithril redraw.
 */
export default class ScrollWidgets extends Component {
  frame = 0;
  onScroll = () => {
    if (this.frame) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = 0;
      this.update();
    });
  };
  oncreate(vnode) {
    super.oncreate(vnode);
    window.addEventListener('scroll', this.onScroll, {
      passive: true
    });
    window.addEventListener('resize', this.onScroll, {
      passive: true
    });
    this.update();
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    this.update();
  }
  onremove(vnode) {
    super.onremove(vnode);
    window.removeEventListener('scroll', this.onScroll);
    window.removeEventListener('resize', this.onScroll);
    if (this.frame) cancelAnimationFrame(this.frame);
  }
  isDiscussion() {
    return !!app.current.data.routeName?.startsWith('discussion');
  }
  view() {
    const {
      config
    } = this.attrs;
    return m("div", {
      className: "FyScrollWidgets"
    }, config.progressBar && this.isDiscussion() ? m("div", {
      className: "FyProgress",
      "aria-hidden": "true"
    }, m("div", {
      className: "FyProgress-bar"
    })) : null, config.backToTop ? m("button", {
      type: "button",
      className: "FyBackToTop",
      "aria-label": app.translator.trans('fy-theme.forum.back_to_top', {}, true),
      onclick: () => window.scrollTo({
        top: 0,
        behavior: 'smooth'
      })
    }, m(Icon, {
      name: "fas fa-arrow-up"
    })) : null);
  }
  update() {
    const element = this.element;
    if (!element) return;
    const doc = document.documentElement;
    const max = doc.scrollHeight - window.innerHeight;
    const progress = max > 0 ? Math.min(1, Math.max(0, window.scrollY / max)) : 0;
    element.style.setProperty('--fy-progress', String(progress));
    element.querySelector('.FyBackToTop')?.classList.toggle('is-visible', window.scrollY > window.innerHeight * 0.8);
  }
}
flarum.reg.add('soup-97-fy-theme', 'forum/components/ScrollWidgets', ScrollWidgets);